const cfg = $('Config').first().json;
const run = $('Begin Run').item.json;
const doc = $json;

if (!doc.raw_content || !doc.raw_content.trim()) throw new Error('source document is empty');

const systemPrompt = "You extract structured product data from a supplier's information document (info.md). Documents are messy: plain text, emoji bullets, typos, mixed Markdown, price lists and delivery lists.\nRULES\n1. A product is something a customer can buy, identified by a title, a heading, or a price-list heading. Section headers (Price, Sizes, Colours, Fabric, Delivery, Notes), option lists, surcharges, sizes and delivery areas are NEVER products.\n2. Every product needs source_excerpt: a short passage (<=120 chars) copied VERBATIM from the document that proves the product exists. Never invent products, names, prices or areas.\n3. If the document has no product title, use a clearly provisional descriptive name, confidence <= 0.5 and needs_review true.\n4. Keep every price as its own entry with raw_text copied verbatim. Use variants for sizes/styles/configurations, put frame/set/fitting splits in components. Currency from the symbol (£=GBP). If a price is ambiguous set needs_review true and a low confidence.\n5. Optional extras / add-ons go in options (is_included=false). Dimensions, materials and other specifications go in specifications or facts.\n6. Delivery areas, schedules, charges and payment terms apply to the whole document: put them in fulfilment_terms (areas as {name, postcode?}). Do not invent payment terms; if absent, say so in warnings.\n7. Anything you cannot classify confidently goes into unclassified_content with a reason. Never drop information and never turn it into a product.\n8. Respond ONLY by calling the record_extraction tool.";

const request = {
  model: "nvidia/nemotron-3-ultra-550b-a55b:free",
  max_tokens: cfg.max_tokens || 4096,
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: 'File: ' + (doc.source_filename || 'info.md') + '\n\n<document>\n' + doc.raw_content + '\n</document>' }
  ],
  tools: [{
    type: "function",
    function: {
      name: 'record_extraction',
      description: 'Record the structured extraction of this document.',
      parameters: {"type": "object", "required": ["products"], "properties": {"products": {"type": "array", "items": {"type": "object", "required": ["name", "source_excerpt", "confidence"], "properties": {"name": {"type": "string"}, "description": {"type": "string"}, "category": {"type": "string"}, "confidence": {"type": "number"}, "needs_review": {"type": "boolean"}, "notes": {"type": "string"}, "source_excerpt": {"type": "string"}, "specifications": {"type": "object"}, "variants": {"type": "array", "items": {"type": "object", "required": ["name"], "properties": {"name": {"type": "string"}, "configuration": {"type": "string"}, "attributes": {"type": "object"}, "source_label": {"type": "string"}, "sort_order": {"type": "integer"}}}}, "prices": {"type": "array", "items": {"type": "object", "required": ["raw_text"], "properties": {"kind": {"type": "string"}, "label": {"type": "string"}, "variant": {"type": "string"}, "amount": {"type": ["number", "null"]}, "currency": {"type": "string"}, "unit": {"type": "string"}, "applies_to": {"type": "string"}, "components": {"type": "object"}, "conditions": {"type": "object"}, "raw_text": {"type": "string"}, "confidence": {"type": "number"}, "needs_review": {"type": "boolean"}}}}, "options": {"type": "array", "items": {"type": "object", "required": ["name"], "properties": {"name": {"type": "string"}, "group": {"type": "string"}, "type": {"type": "string"}, "description": {"type": "string"}, "is_included": {"type": "boolean"}, "attributes": {"type": "object"}, "source_excerpt": {"type": "string"}}}}, "facts": {"type": "array", "items": {"type": "object", "required": ["key"], "properties": {"group": {"type": "string"}, "key": {"type": "string"}, "value": {"type": "string"}, "unit": {"type": "string"}, "raw_text": {"type": "string"}}}}}}}, "fulfilment_terms": {"type": "array", "items": {"type": "object", "properties": {"term_type": {"type": "string", "enum": ["delivery", "payment", "charges", "returns", "other"]}, "label": {"type": "string"}, "areas": {"type": "array", "items": {"type": "object"}}, "schedules": {"type": "object"}, "charges": {"type": "array", "items": {"type": "object"}}, "payment_methods": {"type": "array", "items": {"type": "object"}}, "conditions": {"type": "object"}, "raw_terms": {"type": "string"}}}}, "unclassified_content": {"type": "array", "items": {"type": "object", "properties": {"type": {"type": "string"}, "text": {"type": "string"}, "reason": {"type": "string"}}}}, "warnings": {"type": "array", "items": {"type": "string"}}, "overall_confidence": {"type": "number"}}}
    }
  }],
  tool_choice: { type: 'function', function: { name: 'record_extraction' } }
};

return { json: { request, run_id: run.run_id, source_document_id: doc.id } };

const resp = $json;
const run = $('Begin Run').item.json;

// Check if the response was truncated by max tokens
if (resp.choices && resp.choices[0] && resp.choices[0].finish_reason === 'length') {
  throw new Error('LLM output truncated (max_tokens); raise max_tokens or chunk the document');
}

// Extract the message content from OpenAI/OpenRouter format
const message = resp.choices && resp.choices[0] && resp.choices[0].message;
if (!message) throw new Error('LLM returned no message choices');

let p;
try {
  // If the model responded with tool calls (OpenAI style)
  if (message.tool_calls && message.tool_calls.length > 0) {
    const toolCall = message.tool_calls.find(tc => tc.function && tc.function.name === 'record_extraction');
    if (!toolCall) throw new Error('LLM returned no record_extraction tool call');
    p = JSON.parse(toolCall.function.arguments);
  } else if (message.content) {
    // Fallback: parse JSON directly if the model outputted it as plain text content
    let rawText = message.content.trim();
    if (rawText.startsWith('```json')) {
      rawText = rawText.replace(/^```json/, '').replace(/```$/, '').trim();
    } else if (rawText.startsWith('```')) {
      rawText = rawText.replace(/^```/, '').replace(/```$/, '').trim();
    }
    p = JSON.parse(rawText);
  } else {
    throw new Error('LLM response content is empty');
  }
} catch (e) {
  throw new Error('Failed to parse LLM structured output: ' + e.message);
}

if (!p || !Array.isArray(p.products)) throw new Error('payload.products is not an array');

const num = v => { 
  if (typeof v === 'number') return Number.isFinite(v) ? v : null; 
  if (typeof v === 'string') { const n = parseFloat(v.replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : null; } 
  return null; 
};

const clamp = v => { 
  const n = num(v); 
  return n === null ? 0 : Math.min(1, Math.max(0, n)); 
};

p.products = p.products.filter(x => x && typeof x.name === 'string').map(x => {
  x.confidence = clamp(x.confidence);
  x.prices = (x.prices || []).map(pr => { 
    const a = num(pr.amount); 
    return { ...pr, amount: a, needs_review: !!pr.needs_review || a === null, confidence: pr.confidence === undefined ? undefined : clamp(pr.confidence) }; 
  });
  return x;
});

p.overall_confidence = clamp(p.overall_confidence);
p.warnings = [...(p.warnings || []), 'model=' + (resp.model || 'unknown') + ' usage=' + JSON.stringify(resp.usage || {})];

return { json: { run_id: run.run_id, payload: p } };

const out = { applied: 0, failed: 0, skipped_already_done: 0, by_status: {} };
const safe = n => { try { return $(n).all(); } catch (e) { return []; } };
for (const i of safe('Apply Extraction')) { out.applied++; const s = i.json.status || 'unknown'; out.by_status[s] = (out.by_status[s] || 0) + 1; }
out.failed = safe('Record Failure').length;
out.skipped_already_done = safe('Skip (already done)').length;
return [{ json: out }];
